import{_ as e,o as a,c as r,a3 as n}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"工作流原理与边界","description":"弄清状态图解决什么、与 Chain / createAgent / 多 Agent 如何分工、端到端分哪几段，以及何时不要上图。","frontmatter":{"title":"工作流原理与边界","description":"弄清状态图解决什么、与 Chain / createAgent / 多 Agent 如何分工、端到端分哪几段，以及何时不要上图。","outline":[2,3],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"ts-ai/workflow/workflow-foundations/workflow-principles-boundaries.md","filePath":"ts-ai/workflow/workflow-foundations/workflow-principles-boundaries.md","lastUpdated":1786113687000}'),d={name:"ts-ai/workflow/workflow-foundations/workflow-principles-boundaries.md"};function o(s,t,i,l,h,c){return a(),r("div",null,[...t[0]||(t[0]=[n(`<h1 id="工作流原理与边界" tabindex="-1">工作流原理与边界 <a class="header-anchor" href="#工作流原理与边界" aria-label="Permalink to &quot;工作流原理与边界&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p>会调 <code>createAgent</code> 不等于会做可恢复流程。本篇先定<strong>状态图</strong>的问题边界与端到端阶段，再说明和固定 Chain、单 Agent、多 Agent 怎么分。跑通代码见下一篇 <a href="/ts-ai/workflow/workflow-foundations/minimal-stategraph-skeleton">最小可运行 StateGraph</a>。</p><p><strong>目标读者：</strong> 已能使用 <code>createAgent</code> 或 LCEL Chain，尚未系统写过 LangGraph.js 图。<br><strong>前置：</strong> <a href="/ts-ai/agent/runtime/agent-chain-workflow-boundaries">Agent、Chain 与 Workflow 的边界</a>。</p><h2 id="_1-工作流-状态图-解决什么问题" tabindex="-1">1. 工作流（状态图）解决什么问题 <a class="header-anchor" href="#_1-工作流-状态图-解决什么问题" aria-label="Permalink to &quot;1. 工作流（状态图）解决什么问题&quot;">​</a></h2><h3 id="_1-1-定义-显式状态、节点与终态" tabindex="-1">1.1 定义：显式状态、节点与终态 <a class="header-anchor" href="#_1-1-定义-显式状态、节点与终态" aria-label="Permalink to &quot;1.1 定义：显式状态、节点与终态&quot;">​</a></h3><p><strong>工作流（Workflow）</strong> 在本手册指用 LangGraph.js <strong><code>StateGraph</code></strong> 表达的控制流：状态通道是共享内存，节点写局部更新，边（含条件边）决定下一步，直到到达终态。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入 State</span></span>
<span class="line"><span>  → 节点 A 返回部分更新（Reducer 合并）</span></span>
<span class="line"><span>  → 条件边按字段路由到 B / C</span></span>
<span class="line"><span>  → 汇聚 / 终态节点</span></span>
<span class="line"><span>  → 输出最终 State</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>关键点不是「多调几次模型」，而是：<strong>控制流与业务状态成为一等数据</strong>——可测试、可观察、可在中断后按同一张图恢复。</p><h3 id="_1-2-与固定-chain-的对比" tabindex="-1">1.2 与固定 Chain 的对比 <a class="header-anchor" href="#_1-2-与固定-chain-的对比" aria-label="Permalink to &quot;1.2 与固定 Chain 的对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>固定 Chain（LCEL <code>pipe</code>）</th><th>Workflow（<code>StateGraph</code>）</th></tr></thead><tbody><tr><td>控制流</td><td>编译期写死的管道</td><td>节点 + 边 + 条件路由，可循环/并行</td></tr><tr><td>状态</td><td>通常一次输入→一次输出</td><td>多通道 State，跨节点累积</td></tr><tr><td>适合</td><td>ETL 式 Prompt→Model→Parse</td><td>分支、汇聚、持久暂停、审批</td></tr><tr><td>失败样子</td><td>某步解析失败整链停</td><td>路由错、Reducer 合并错、无法到达 <code>END</code></td></tr></tbody></table><p>步骤完全线性、无 mid-run 决策时，Chain 更简单。需要「分类后走不同处理再汇总」、或中途人工签核时，再上图。选型决策见前置文。</p><h3 id="_1-3-与单-agent-createagent-的对比" tabindex="-1">1.3 与单 Agent（<code>createAgent</code>）的对比 <a class="header-anchor" href="#_1-3-与单-agent-createagent-的对比" aria-label="Permalink to &quot;1.3 与单 Agent（\`createAgent\`）的对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>单 Agent</th><th>Workflow</th></tr></thead><tbody><tr><td>谁决定下一步</td><td>模型在 ReAct 循环里选工具</td><td><strong>你写的边与路由函数</strong>（节点内仍可调模型）</td></tr><tr><td>控制流可见性</td><td>轨迹在 messages / 工具调用里</td><td>节点名、边、终态可画成图</td></tr><tr><td>适合</td><td>工具集稳定、探索式任务</td><td>严格顺序、并行分支、合规审批</td></tr><tr><td>代价</td><td>轮次与成本难预算</td><td>图建模与状态契约成本</td></tr></tbody></table><p><code>createAgent</code> 底层常是预编译的 ReAct 图，但应用代码不必手写节点。<strong>默认 Harness 表达不了你的控制流时</strong>，再自定义 <code>StateGraph</code>。不要把「再套一层 Agent」当成升级。</p><h3 id="_1-4-与「多-agent」的分工" tabindex="-1">1.4 与「多 Agent」的分工 <a class="header-anchor" href="#_1-4-与「多-agent」的分工" aria-label="Permalink to &quot;1.4 与「多 Agent」的分工&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>单图 Workflow</th><th>多 Agent</th></tr></thead><tbody><tr><td>单位</td><td>一张图上的节点（可为普通函数或子图）</td><td>多个角色 / Agent，再经 Supervisor 或 Handoff 协作</td></tr><tr><td>何时需要</td><td>步骤与状态机已够用</td><td>职责、权限、提示词必须隔离，且单图节点已不可维护</td></tr><tr><td>风险</td><td>单节点塞满业务</td><td>级联调用、永不终止、成本爆炸</td></tr></tbody></table><p>多 Agent 是<strong>进阶</strong>：先证明单图 + Checkpoint / Interrupt 不够，再看 <a href="/ts-ai/workflow/multi-agent/multi-agent-patterns">多 Agent 架构模式</a>。</p><h2 id="_2-端到端阶段" tabindex="-1">2. 端到端阶段 <a class="header-anchor" href="#_2-端到端阶段" aria-label="Permalink to &quot;2. 端到端阶段&quot;">​</a></h2><p>完整图生命周期分四段：<strong>建模 → 执行 → 持久 → 介入</strong>。高级能力都挂在某段上，不能代替这四段。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[建模]  State 通道 → 节点 → 边 / 条件路由 → 终态</span></span>
<span class="line"><span>[执行]  compile → invoke / stream → 观察节点与 State</span></span>
<span class="line"><span>[持久]  Checkpointer + thread_id → 快照与跨进程恢复</span></span>
<span class="line"><span>[介入]  interrupt() → 人工决策 → Command({ resume })</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="_2-1-建模-状态通道、节点、边、终止" tabindex="-1">2.1 建模：状态通道、节点、边、终止 <a class="header-anchor" href="#_2-1-建模-状态通道、节点、边、终止" aria-label="Permalink to &quot;2.1 建模：状态通道、节点、边、终止&quot;">​</a></h3><table tabindex="0"><thead><tr><th>构件</th><th>职责</th></tr></thead><tbody><tr><td><strong>State 通道</strong></td><td>用 <code>Annotation.Root</code> 声明字段；可选 <code>reducer</code> / <code>default</code></td></tr><tr><td><strong>节点</strong></td><td><code>(state) =&gt; Partial&lt;State&gt;</code>；副作用应可幂等或可审计</td></tr><tr><td><strong>边</strong></td><td>固定边或 <code>addConditionalEdges</code> 路由</td></tr><tr><td><strong>终态</strong></td><td><code>END</code> / <code>__end__</code>；必须保证合法输入能到达</td></tr></tbody></table><p>建模深讲见 <a href="/ts-ai/workflow/langgraph-core/workflow-modeling">工作流建模</a> 与 <a href="/ts-ai/workflow/langgraph-core/state-graph">StateGraph</a>。</p><h3 id="_2-2-执行-invoke-stream、一次-run-的观察点" tabindex="-1">2.2 执行：invoke / stream、一次 Run 的观察点 <a class="header-anchor" href="#_2-2-执行-invoke-stream、一次-run-的观察点" aria-label="Permalink to &quot;2.2 执行：invoke / stream、一次 Run 的观察点&quot;">​</a></h3><p><code>compile()</code> 得到可调用图。<code>invoke(input)</code> 跑完整路径并返回最终 State；<code>stream</code> / <code>streamEvents</code> 暴露逐步更新，便于对照「当前节点 → 通道变化 → 下一条边」。</p><p>一次 Run 至少能回答：走过哪些节点、条件边选了哪支、最终 State 是否符合契约。测法见 <a href="/ts-ai/workflow/workflow-quality/graph-testing">Graph 测试</a>。</p><h3 id="_2-3-持久-checkpoint、线程、恢复" tabindex="-1">2.3 持久：Checkpoint、线程、恢复 <a class="header-anchor" href="#_2-3-持久-checkpoint、线程、恢复" aria-label="Permalink to &quot;2.3 持久：Checkpoint、线程、恢复&quot;">​</a></h3><p>Checkpointer 在步骤边界写入快照；<code>configurable.thread_id</code> 标识同一条执行线程。进程重启后可用同一 <code>thread_id</code> 继续。</p><table tabindex="0"><thead><tr><th>视角</th><th>归属</th></tr></thead><tbody><tr><td><strong>图执行</strong>：快照何时写、如何 resume、与 Interrupt 配合</td><td>本模块 <a href="/ts-ai/workflow/durable-execution/checkpoint-store">图持久化：Checkpointer 与 Checkpoint</a></td></tr><tr><td><strong>记忆语义</strong>：短期消息、长期事实、租户隔离</td><td><a href="/ts-ai/knowledge/memory/checkpoint-store">记忆视角：Checkpoint 与 Store</a></td></tr></tbody></table><p><code>MemorySaver</code> 只适合开发演示；跨天审批需 Postgres 等持久 Checkpointer。</p><h3 id="_2-4-介入-interrupt-与人工决策" tabindex="-1">2.4 介入：Interrupt 与人工决策 <a class="header-anchor" href="#_2-4-介入-interrupt-与人工决策" aria-label="Permalink to &quot;2.4 介入：Interrupt 与人工决策&quot;">​</a></h3><p>节点内调用 <code>interrupt(value)</code> 会暂停图并把 <code>value</code> 暴露给调用方；用 <code>Command({ resume })</code> 恢复，使 <code>interrupt()</code> 返回人工输入。需要 Checkpointer，否则暂停无法跨请求存活。API 见 <a href="/ts-ai/workflow/durable-execution/interrupt-command">Interrupt 与 Command</a>。</p><p>前端「点一下确认再调工具」若<strong>不要求</strong>跨进程恢复图状态，可能只是会话确认，不必上 Interrupt——见组装配方决策表。</p><h3 id="_2-5-各阶段失败时的典型症状" tabindex="-1">2.5 各阶段失败时的典型症状 <a class="header-anchor" href="#_2-5-各阶段失败时的典型症状" aria-label="Permalink to &quot;2.5 各阶段失败时的典型症状&quot;">​</a></h3><table tabindex="0"><thead><tr><th>症状</th><th>优先怀疑阶段</th></tr></thead><tbody><tr><td>编译报错、找不到节点 / 边</td><td>建模</td></tr><tr><td>条件边漏映射、永远到不了 <code>END</code></td><td>建模 / 路由</td></tr><tr><td>Reducer 把数组盖成标量、字段丢失</td><td>建模：通道合并</td></tr><tr><td>重启后审批半截消失</td><td>持久：无 Checkpointer 或 <code>thread_id</code> 错</td></tr><tr><td><code>interrupt</code> 后无法 resume</td><td>介入：未用 <code>Command</code>，或 checkpointer 丢失</td></tr><tr><td>队列重试导致重复扣款</td><td>持久 + 副作用幂等（见 durable-execution）</td></tr></tbody></table><h2 id="_3-核心对象与所有权" tabindex="-1">3. 核心对象与所有权 <a class="header-anchor" href="#_3-核心对象与所有权" aria-label="Permalink to &quot;3. 核心对象与所有权&quot;">​</a></h2><h3 id="_3-1-state-node-edge-graph-checkpointer" tabindex="-1">3.1 State / Node / Edge / Graph / Checkpointer <a class="header-anchor" href="#_3-1-state-node-edge-graph-checkpointer" aria-label="Permalink to &quot;3.1 State / Node / Edge / Graph / Checkpointer&quot;">​</a></h3><table tabindex="0"><thead><tr><th>对象</th><th>职责</th></tr></thead><tbody><tr><td><strong>State</strong></td><td>图共享数据；由 <code>Annotation</code> 定义通道与合并规则</td></tr><tr><td><strong>Node</strong></td><td>纯函数式更新（可含模型 / 工具调用）；返回<strong>部分</strong> State</td></tr><tr><td><strong>Edge</strong></td><td>控制流；条件边把 State 映射到下一节点名</td></tr><tr><td><strong>Graph</strong></td><td><code>StateGraph</code> 装配后经 <code>compile</code> 成为可执行对象</td></tr><tr><td><strong>Checkpointer</strong></td><td>步骤快照存储；<code>MemorySaver</code> / Postgres 等实现</td></tr></tbody></table><h3 id="_3-2-本模块与别章职责对照" tabindex="-1">3.2 本模块与别章职责对照 <a class="header-anchor" href="#_3-2-本模块与别章职责对照" aria-label="Permalink to &quot;3.2 本模块与别章职责对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>主题</th><th>本模块讲</th><th>别章讲</th></tr></thead><tbody><tr><td>Chain vs Agent vs 图选型</td><td>图侧边界与阶段</td><td><a href="/ts-ai/agent/runtime/agent-chain-workflow-boundaries">Agent、Chain 与 Workflow 的边界</a></td></tr><tr><td>Checkpoint 记忆语义</td><td>图执行快照与恢复</td><td><a href="/ts-ai/knowledge/memory/checkpoint-store">记忆视角：Checkpoint 与 Store</a></td></tr><tr><td>队列基础设施</td><td>图 Job 与状态边界</td><td><a href="/ts-ai/backend/data-tasks/bullmq-reliable-workers">BullMQ</a>；<code>agent-run</code> ≠ 图 Job</td></tr><tr><td>HITL UI</td><td>Interrupt / Command 契约</td><td><a href="/ts-ai/integration/ai-interaction/tool-confirmation-human-loop">工具确认与人在回路</a></td></tr><tr><td>全站观测 / SLO</td><td>图路径与节点延迟</td><td><a href="/ts-ai/quality/">质量与生产</a></td></tr></tbody></table><h2 id="_4-何时用-何时不用" tabindex="-1">4. 何时用 / 何时不用 <a class="header-anchor" href="#_4-何时用-何时不用" aria-label="Permalink to &quot;4. 何时用 / 何时不用&quot;">​</a></h2><h3 id="_4-1-适合上图的场景" tabindex="-1">4.1 适合上图的场景 <a class="header-anchor" href="#_4-1-适合上图的场景" aria-label="Permalink to &quot;4.1 适合上图的场景&quot;">​</a></h3><ul><li>固定「分类 → 分支处理 → 汇总」且每支要测路径</li><li>需要并行子任务再汇聚</li><li>需要 mid-run 人工审批，且暂停可能跨小时 / 跨进程</li><li>需要确定性 replay、状态迁移测试或图版本升级</li></ul><h3 id="_4-2-应留在-chain-agent-的场景" tabindex="-1">4.2 应留在 Chain / Agent 的场景 <a class="header-anchor" href="#_4-2-应留在-chain-agent-的场景" aria-label="Permalink to &quot;4.2 应留在 Chain / Agent 的场景&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>更合适的做法</th></tr></thead><tbody><tr><td>单次 Prompt → 结构化输出</td><td>Chain 或裸 ChatModel</td></tr><tr><td>工具 ≤2、探索式查数</td><td><code>createAgent</code></td></tr><tr><td>无分支、无暂停的线性 ETL</td><td>LCEL <code>pipe</code></td></tr><tr><td>只想「多几个角色人设」</td><td>先拆 Prompt / 工具，不要先上 Supervisor</td></tr></tbody></table><h3 id="_4-3-最小闭环判定-能否不配多-agent-先上线" tabindex="-1">4.3 最小闭环判定（能否不配多 Agent 先上线） <a class="header-anchor" href="#_4-3-最小闭环判定-能否不配多-agent-先上线" aria-label="Permalink to &quot;4.3 最小闭环判定（能否不配多 Agent 先上线）&quot;">​</a></h3><p>若下列都满足，可以先不上多 Agent、不上复杂子图网：</p><ol><li>单张图能表达全部必经步骤与终态</li><li>关键路径有测试（含非法路由）</li><li>需要暂停时，Interrupt + Checkpointer + <code>thread_id</code> 已跑通</li><li>副作用节点有幂等键或「只执行一次」策略</li></ol><p>达不到时，优先修 State 契约与路由，而不是加 Supervisor。</p><h2 id="_5-学习路径与下一篇" tabindex="-1">5. 学习路径与下一篇 <a class="header-anchor" href="#_5-学习路径与下一篇" aria-label="Permalink to &quot;5. 学习路径与下一篇&quot;">​</a></h2><h3 id="_5-1-本篇之后读什么" tabindex="-1">5.1 本篇之后读什么 <a class="header-anchor" href="#_5-1-本篇之后读什么" aria-label="Permalink to &quot;5.1 本篇之后读什么&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>本篇（边界与阶段）</span></span>
<span class="line"><span>  → 最小可运行 StateGraph（无 Checkpoint）</span></span>
<span class="line"><span>  → LangGraph.js 核心 → 持久执行</span></span>
<span class="line"><span>  → 工作流质量 →（可选）多 Agent</span></span>
<span class="line"><span>  → 组装配方与自检</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="_5-2-何时再碰多-agent" tabindex="-1">5.2 何时再碰多 Agent <a class="header-anchor" href="#_5-2-何时再碰多-agent" aria-label="Permalink to &quot;5.2 何时再碰多 Agent&quot;">​</a></h3><p><a href="/ts-ai/workflow/multi-agent/">多 Agent</a> 标为<strong>进阶</strong>。仅在单图 + 持久执行已通过，且评测/成本证明「单角色节点不够」时再引入。不要用多 Agent 掩盖混乱的 State 与缺失的终态条件。</p><p>下一篇：<a href="/ts-ai/workflow/workflow-foundations/minimal-stategraph-skeleton">最小可运行 StateGraph</a>。</p>`,56)])])}const b=e(d,[["render",o]]);export{u as __pageData,b as default};
